    command = _normalise_argv(argv)
    handles = _normalise_handles(inherit)

    kwargs = {
        # The helper is expected to need the objects it is handed, so close_fds
        # stays off; otherwise the log pipe is gone before the helper starts.
        "close_fds": False,
        "stdin": stdin,
        "stdout": stdout,
        "stderr": stderr,
    }
