        raise WSpawnError("inherit must be a sequence of handles, not a single handle", kind="badarg")
    if isinstance(inherit, (str, bytes)):
        raise WSpawnError("inherit must be a sequence of handles, not a string", kind="badarg")
    try:
        items = list(inherit)
    except TypeError as exc:
        raise WSpawnError("inherit must be an iterable of handles: %s" % exc,
                          kind="badarg") from exc
    handles = []
    for item in items:
        if isinstance(item, bool) or not isinstance(item, int):
            if hasattr(item, "fileno"):
                try:
                    item = item.fileno()
                except (OSError, ValueError) as exc:
                    raise WSpawnError("inherit entry has no usable descriptor: %s" % exc,
                                      kind="badarg") from exc
            else:
                raise WSpawnError("inherit must contain integer handles, got %r" % (item,),
                                  kind="badarg")
        handles.append(int(item))
    return tuple(handles)


def _resolve_stream(value, opened, stdout_resolved=None, name="stream"):
    """Return the Win32 handle a ``stdin``/``stdout``/``stderr`` value names."""
    if value is None:
        return None
    # ``subprocess.PIPE`` and friends are small negative integers; check them
    # explicitly before falling back to raw handle logic.
    if value is _PIPE or (isinstance(value, int) and not isinstance(value, bool)
                          and value == _PIPE):
        raise WSpawnError(
            "%s=PIPE is not supported: hand wspawn a pipe you created yourself "
            "and list it in inherit" % name,
            kind="unsupported",
        )
    if isinstance(value, int) and not isinstance(value, bool) and value == _DEVNULL:
        handle = _winapi.open_nul()
        opened.append(handle)
        return handle
    if isinstance(value, int) and not isinstance(value, bool) and value == _STDOUT:
        if name != "stderr":
            raise WSpawnError("STDOUT is only meaningful for stderr", kind="badarg")
        return stdout_resolved
    if hasattr(value, "fileno"):
        try:
            descriptor = value.fileno()
        except (OSError, ValueError) as exc:
            raise WSpawnError("%s has no usable descriptor: %s" % (name, exc),
                              kind="badarg") from exc
        try:
            value.flush()
        except Exception:
            pass
        return _winapi.handle_from_fd(descriptor)
    if isinstance(value, int) and not isinstance(value, bool):
        return _winapi.resolve_handle(value)
    raise WSpawnError("%s must be None, DEVNULL, a handle or a file object, got %r"
                      % (name, value), kind="badarg")


def _default_std(which):
    """Return the parent's standard handle, or ``None`` when it is unusable."""
    try:
        return _winapi.get_std_handle(which)
    except WSpawnError:
        return None


def spawn(argv, inherit=(), stdin=None, stdout=None, stderr=None):
    """Start a helper process, handing it the objects named in ``inherit``.

    The child can reach *only* the objects in ``inherit`` plus the standard
    streams named by ``stdin``/``stdout``/``stderr``.  Every other object the
    caller holds open - even one marked inheritable - stays out of the child.

    Returns a :class:`SpawnedProcess`.
    """
    command = _normalise_argv(argv)
    handles = _normalise_handles(inherit)

    _winapi.require_windows("spawn")

    opened = []
    try:
        resolved_inherit = []
        for raw in handles:
            resolved = _winapi.resolve_handle(raw)
            if _winapi.is_invalid_handle(resolved):
                raise WSpawnError("inherit contains an unusable handle: %r" % (raw,),
                                  kind="badarg", handle=raw)
            if _winapi.is_pseudo_handle(resolved):
                raise WSpawnError("pseudo handles cannot be handed to a child: %r" % (raw,),
                                  kind="unsupported", handle=raw)
            if _winapi.try_handle_information(resolved) is None:
                raise WSpawnError("inherit contains an unusable handle: %r" % (raw,),
                                  kind="badarg", handle=raw)
            resolved_inherit.append(resolved)

        std_in = _resolve_stream(stdin, opened, name="stdin")
        std_out = _resolve_stream(stdout, opened, name="stdout")
        std_err = _resolve_stream(stderr, opened, stdout_resolved=std_out, name="stderr")

        if std_in is None:
            std_in = _default_std(_winapi.STD_INPUT_HANDLE)
        if std_out is None:
            std_out = _default_std(_winapi.STD_OUTPUT_HANDLE)
        if std_err is None:
            std_err = _default_std(_winapi.STD_ERROR_HANDLE)

        # Everything the child may reach: the handover plus the standard
        # streams it was told to use.  Order is irrelevant, duplicates are not
        # allowed in a handle list.
        handle_list = []
        for item in resolved_inherit:
            if item not in handle_list:
                handle_list.append(item)

        std_slots = {"stdin": std_in, "stdout": std_out, "stderr": std_err}
        for slot in ("stdin", "stdout", "stderr"):
            item = std_slots[slot]
            if item is None or _winapi.is_invalid_handle(item):
                std_slots[slot] = None
                continue
            if _winapi.try_handle_information(item) is None:
                # Not a real kernel object we can hand over (for example a
                # closed stream); do not pretend the child can use it.
                std_slots[slot] = None
                continue
            if item not in handle_list:
                handle_list.append(item)

        # Mark the handover inheritable for the duration of the call, keeping
        # the caller's flags intact afterwards.
        restore = []
        try:
            for item in list(handle_list):
                flags = _winapi.try_handle_information(item)
                if flags is None:
                    handle_list.remove(item)
                    continue
                if not (flags & _winapi.HANDLE_FLAG_INHERIT):
                    try:
                        _winapi.set_handle_information(
                            item, _winapi.HANDLE_FLAG_INHERIT, _winapi.HANDLE_FLAG_INHERIT
                        )
                    except WSpawnError:
                        if item in resolved_inherit:
                            raise
                        # A standard stream that cannot be handed over; drop it
                        # rather than failing the whole spawn.
                        handle_list.remove(item)
                        for slot, value in std_slots.items():
                            if value == item:
                                std_slots[slot] = None
                        continue
                    restore.append(item)

            if not handle_list:
                # An empty PROC_THREAD_ATTRIBUTE_HANDLE_LIST is rejected by
                # Windows, and "no objects at all" is exactly what a bare
                # ``spawn(argv)`` asks for.  Hand over a private NUL handle so
                # the list is well formed and the child still reaches nothing of
                # the caller's.
                filler = _winapi.open_nul()
                opened.append(filler)
                handle_list.append(filler)

            command_line = subprocess.list2cmdline(command)
            process_handle, pid = _winapi.create_process(
                command_line,
                handle_list,
                (std_slots["stdin"], std_slots["stdout"], std_slots["stderr"]),
            )
        finally:
            for item in restore:
                try:
                    _winapi.set_handle_information(item, _winapi.HANDLE_FLAG_INHERIT, 0)
                except WSpawnError:
                    pass
    finally:
        for item in opened:
            _winapi.close_handle(item)

    return SpawnedProcess(process_handle, pid, handles)

"""Starting helper processes with a handover of the caller's objects.

The handover is implemented with the Windows process-creation primitives that
actually constrain what a child can reach:

* ``CreateProcessW`` is called with ``bInheritHandles=TRUE`` *and* a
  ``PROC_THREAD_ATTRIBUTE_HANDLE_LIST`` naming exactly the objects the caller
  handed over.  Windows then gives the child **only** those objects, no matter
  what else in the parent happens to be marked inheritable.
* Handle values are preserved across inheritance, so the numbers the caller
  holds are the numbers the child can use.
* Objects that are handed over are marked inheritable for the duration of the
  call; the caller's original flags are restored afterwards.
* A standard stream the caller did not name is backed by a private ``NUL``
  handle rather than by the host's own stream, so an unnamed stream never
  becomes an accidental handover.
"""

import os
import subprocess

from . import _winapi
from .errors import WSpawnError

_DEVNULL = getattr(subprocess, "DEVNULL", -3)
_PIPE = getattr(subprocess, "PIPE", -1)
_STDOUT = getattr(subprocess, "STDOUT", -2)


class SpawnedProcess(object):
    """A helper process started by :func:`spawn`."""

    def __init__(self, process_handle, pid, inherit):
        self._handle = process_handle
        self.inherit = tuple(inherit)
        self.pid = pid
        self.returncode = None

    @property
    def handle(self):
        """The process handle, or ``None`` once it has been released."""
        return self._handle

    def wait(self, timeout=None):
        """Wait for the helper to exit and return its exit code."""
        if self.returncode is not None:
            return self.returncode
        if self._handle is None:
            raise WSpawnError("the process handle has already been released", kind="badarg")
        if timeout is None:
            milliseconds = _winapi.INFINITE
        else:
            try:
                milliseconds = int(float(timeout) * 1000)
            except (TypeError, ValueError) as exc:
                raise WSpawnError("timeout must be a number of seconds: %s" % exc,
                                  kind="badarg") from exc
            if milliseconds < 0:
                milliseconds = 0
        result = _winapi.wait_for_single_object(self._handle, milliseconds)
        if result == _winapi.WAIT_TIMEOUT:
            raise subprocess.TimeoutExpired(cmd=None, timeout=timeout)
        self.returncode = _winapi.get_exit_code_process(self._handle)
        return self.returncode

    def poll(self):
        """Return the exit code if the helper has finished, else ``None``."""
        if self.returncode is not None:
            return self.returncode
        if self._handle is None:
            return None
        result = _winapi.wait_for_single_object(self._handle, 0)
        if result == _winapi.WAIT_TIMEOUT:
            return None
        self.returncode = _winapi.get_exit_code_process(self._handle)
        return self.returncode

    def terminate(self):
        """Terminate the helper."""
        if self._handle is None:
            raise WSpawnError("the process handle has already been released", kind="badarg")
        if self.returncode is not None:
            return
        _winapi.terminate_process(self._handle, 1)

    kill = terminate

    def close(self):
        """Release the process handle."""
        if self._handle is not None:
            _winapi.close_handle(self._handle)
            self._handle = None

    def __del__(self):
        try:
            self.close()
        except Exception:
            pass


def _normalise_argv(argv):
    if isinstance(argv, (str, bytes)):
        raise WSpawnError("argv must be a sequence of arguments, not a single string", kind="badarg")
    try:
        items = [os.fspath(item) for item in argv]
    except TypeError as exc:
        raise WSpawnError("argv must be an iterable of paths: %s" % exc, kind="badarg") from exc
    cleaned = []
    for item in items:
        if isinstance(item, bytes):
            item = os.fsdecode(item)
        cleaned.append(item)
    if not cleaned:
        raise WSpawnError("argv must not be empty", kind="badarg")
    return cleaned


def _normalise_handles(inherit):
    if inherit is None:
        return ()
    if isinstance(inherit, int):
        raise WSpawnError("inherit must be a sequence of handles, not a single handle", kind="badarg")
    if isinstance(inherit, (str, bytes)):
        raise WSpawnError("inherit must be a sequence of handles, not a string", kind="badarg")
    try:
        items = list(inherit)
    except TypeError as exc:
        raise WSpawnError("inherit must be an iterable of handles: %s" % exc,
                          kind="badarg") from exc
    handles = []
    for item in items:
        if isinstance(item, bool) or not isinstance(item, int):
            if hasattr(item, "fileno"):
                try:
                    item = item.fileno()
                except (OSError, ValueError) as exc:
                    raise WSpawnError("inherit entry has no usable descriptor: %s" % exc,
                                      kind="badarg") from exc
            else:
                raise WSpawnError("inherit must contain integer handles, got %r" % (item,),
                                  kind="badarg")
        handles.append(int(item))
    return tuple(handles)


def _is_sentinel(value, sentinel):
    return (isinstance(value, int) and not isinstance(value, bool) and value == sentinel)


def _resolve_stream(value, opened, stdout_resolved=None, name="stream"):
    """Return the Win32 handle a ``stdin``/``stdout``/``stderr`` value names.

    ``None`` is returned for a stream the caller did not name.
    """
    if value is None:
        return None
    # ``subprocess.PIPE``/``DEVNULL``/``STDOUT`` are small negative integers;
    # they must be recognised before anything is treated as a raw handle.
    if _is_sentinel(value, _PIPE):
        raise WSpawnError(
            "%s=PIPE is not supported: create the pipe yourself and name it in "
            "inherit so the handover stays explicit" % name,
            kind="unsupported",
        )
    if _is_sentinel(value, _DEVNULL):
        handle = _winapi.open_nul()
        opened.append(handle)
        return handle
    if _is_sentinel(value, _STDOUT):
        if name != "stderr":
            raise WSpawnError("STDOUT is only meaningful for stderr", kind="badarg")
        if stdout_resolved is None:
            raise WSpawnError("stderr=STDOUT needs an explicit stdout", kind="badarg")
        return stdout_resolved
    # A file object names a C runtime descriptor, never a handle.
    if hasattr(value, "fileno"):
        try:
            descriptor = value.fileno()
        except (OSError, ValueError) as exc:
            raise WSpawnError("%s has no usable descriptor: %s" % (name, exc),
                              kind="badarg") from exc
        try:
            value.flush()
        except Exception:
            pass
        return _winapi.handle_from_fd(descriptor)
    if isinstance(value, int) and not isinstance(value, bool):
        return _winapi.resolve_handle(value)
    raise WSpawnError("%s must be None, DEVNULL, a handle or a file object, got %r"
                      % (name, value), kind="badarg")


def spawn(argv, inherit=(), stdin=None, stdout=None, stderr=None):
    """Start a helper process, handing it the objects named in ``inherit``.

    The child can reach *only* the objects in ``inherit`` plus the standard
    streams named by ``stdin``/``stdout``/``stderr``.  Every other object the
    caller holds open stays out of the child, including objects that are
    currently marked inheritable.  A stream the caller leaves as ``None`` is
    backed by ``NUL`` in the child.

    Returns a :class:`SpawnedProcess`.
    """
    command = _normalise_argv(argv)
    handles = _normalise_handles(inherit)

    _winapi.require_windows("spawn")

    opened = []
    try:
        resolved_inherit = []
        for raw in handles:
            resolved = _winapi.resolve_handle(raw)
            if _winapi.is_invalid_handle(resolved):
                raise WSpawnError("inherit names an unusable handle: %r" % (raw,),
                                  kind="badarg", handle=raw)
            if _winapi.is_pseudo_handle(resolved):
                raise WSpawnError("pseudo handles cannot be handed to a child: %r" % (raw,),
                                  kind="unsupported", handle=raw)
            if _winapi.try_handle_information(resolved) is None:
                raise WSpawnError("inherit names an unusable handle: %r" % (raw,),
                                  kind="badarg", handle=raw)
            resolved_inherit.append(resolved)

        std_in = _resolve_stream(stdin, opened, name="stdin")
        std_out = _resolve_stream(stdout, opened, name="stdout")
        std_err = _resolve_stream(stderr, opened, stdout_resolved=std_out, name="stderr")

        # A stream the caller did not name gets a private NUL handle: the child
        # has a working stream, and none of the host's own streams cross over.
        if std_in is None or std_out is None or std_err is None:
            filler = _winapi.open_nul()
            opened.append(filler)
            if std_in is None:
                std_in = filler
            if std_out is None:
                std_out = filler
            if std_err is None:
                std_err = filler

        # Everything the child may reach: the handover plus the standard
        # streams it was told to use.  A handle list must not repeat a handle.
        handle_list = []
        for item in list(resolved_inherit) + [std_in, std_out, std_err]:
            if item not in handle_list:
                handle_list.append(item)

        # Mark the handover inheritable for the duration of the call, restoring
        # the caller's flags afterwards.
        restore = []
        try:
            for item in handle_list:
                flags = _winapi.try_handle_information(item)
                if flags is None:
                    raise WSpawnError("cannot hand over handle %r" % (item,),
                                      kind="badarg", handle=item)
                if not (flags & _winapi.HANDLE_FLAG_INHERIT):
                    _winapi.set_handle_information(
                        item, _winapi.HANDLE_FLAG_INHERIT, _winapi.HANDLE_FLAG_INHERIT
                    )
                    restore.append(item)

            command_line = subprocess.list2cmdline(command)
            process_handle, pid = _winapi.create_process(
                command_line, handle_list, (std_in, std_out, std_err)
            )
        finally:
            for item in restore:
                try:
                    _winapi.set_handle_information(item, _winapi.HANDLE_FLAG_INHERIT, 0)
                except WSpawnError:
                    pass
    finally:
        for item in opened:
            _winapi.close_handle(item)

    return SpawnedProcess(process_handle, pid, handles)
